int a = 3;
int b = 8;
Tausche(ref a, ref b);
Console.WriteLine($"a = {a}, b = {b}");
// Ausgabe: a = 8, b = 3

void Tausche(ref int x, ref int y)
{
    int hilf = x;
    x = y;
    y = hilf;
}

int[] temperaturen = { 12, 17, 9, 21, 15 };

MinMax(temperaturen, out int kalt, out int warm);
Console.WriteLine($"Tiefstwert: {kalt}, Höchstwert: {warm}");
// Ausgabe: Tiefstwert: 9, Höchstwert: 21

void MinMax(int[] werte, out int min, out int max)
{
    min = werte[0];
    max = werte[0];
    foreach (int w in werte)
    {
        if (w < min) min = w;
        if (w > max) max = w;
    }
}

Console.Write("Wie alt bist du? ");
string eingabe = Console.ReadLine();

if (int.TryParse(eingabe, out int alter))
{
    Console.WriteLine($"In 5 Jahren bist du {alter + 5}.");
}
else
{
    Console.WriteLine($"\"{eingabe}\" ist keine Zahl!");
}
// Eingabe:  zwölf
// Ausgabe: "zwölf" ist keine Zahl!

int zahl;
Console.Write("Zahl: ");
while (!int.TryParse(Console.ReadLine(), out zahl))
{
    Console.Write("Ungültig, nochmal: ");
}
Console.WriteLine($"Danke, {zahl}!");
// Eingabe: abc, dann 7
// Ausgabe: Zahl: Ungültig, nochmal: Danke, 7!

int[] punkte = { 10, 20, 30 };
Verdopple(punkte);
Console.WriteLine(string.Join(" ", punkte));
// Ausgabe: 20 40 60

void Verdopple(int[] werte)
{
    for (int i = 0; i < werte.Length; i++)
    {
        werte[i] = werte[i] * 2;
    }
}

